def raises(exc_type, fn):
    # TODO: call fn(); return True if exc_type raised else False
    pass

lessons.solution_code:
def raises(exc_type, fn):
    try:
        fn()
    except exc_type:
        return True
    return False

tests.unittest_code:
def test_raises(self):
    self.assertTrue(raises(ValueError, lambda: int('x')))
    self.assertFalse(raises(ValueError, lambda: int('3')))

